import uuid

from sqlalchemy.orm import Session

from src.backend.core.base_crud import BaseCRUDService
from src.backend.db.repositories.employee_feedback_repo import (
    create as create_feedback,
    get_by_id as get_feedback_by_id,
    list_items,
    soft_delete as soft_delete_feedback,
    update as update_feedback,
)
from src.backend.models.employee_feedback import EmployeeFeedback
from src.backend.schemas.employee_feedback import EmployeeFeedbackCreate, EmployeeFeedbackUpdate


class EmployeeFeedbackService(BaseCRUDService[EmployeeFeedback]):
    """Service for employee feedback operations."""

    def __init__(self):
        from src.backend.db.repositories.employee_feedback_repo import list_items as list_items_func

        super().__init__(type("Repo", (), {"list_items": list_items_func})())

    def list_feedbacks_service(
        self,
        db: Session,
        page: int = 1,
        page_size: int = 20,
        q: str | None = None,
    ) -> tuple[list[EmployeeFeedback], int, int, int]:
        """List feedback with pagination and search."""
        items, total, page, page_size = self.list_items(db, page, page_size, q)
        return items, total, page, page_size

    def create_feedback_service(
        self,
        db: Session,
        data: EmployeeFeedbackCreate,
        actor_id: uuid.UUID | None,
    ) -> EmployeeFeedback:
        """Create feedback with audit logging."""
        return self.create_item(
            db,
            data,
            actor_id,
            feedback_id=data.feedback_id,
            date=data.date,
            employee_id=data.employee_id,
            survey_period=data.survey_period,
            overall_satisfaction_score=data.overall_satisfaction_score,
            workload_score=data.workload_score,
            learning_score=data.learning_score,
            management_score=data.management_score,
            culture_score=data.culture_score,
            comments=data.comments,
        )

    def get_feedback_service(self, db: Session, feedback_id: uuid.UUID) -> EmployeeFeedback | None:
        """Get feedback by ID."""
        return self.get_item(db, feedback_id)

    def update_feedback_service(
        self,
        db: Session,
        feedback_id: uuid.UUID,
        data: EmployeeFeedbackUpdate,
        actor_id: uuid.UUID | None,
    ) -> EmployeeFeedback | None:
        """Update feedback with audit logging."""
        kwargs = {}
        if data.date is not None:
            kwargs["date"] = data.date
        if data.employee_id is not None:
            kwargs["employee_id"] = data.employee_id
        if data.survey_period is not None:
            kwargs["survey_period"] = data.survey_period
        if data.overall_satisfaction_score is not None:
            kwargs["overall_satisfaction_score"] = data.overall_satisfaction_score
        if data.workload_score is not None:
            kwargs["workload_score"] = data.workload_score
        if data.learning_score is not None:
            kwargs["learning_score"] = data.learning_score
        if data.management_score is not None:
            kwargs["management_score"] = data.management_score
        if data.culture_score is not None:
            kwargs["culture_score"] = data.culture_score
